     1→/**
     2→ * Claude CLI Adapter
     3→ */
     4→
     5→import type { ExecutionResponse, StreamEvent } from '../shared/types';
     6→import { spawnProcess } from '../shared/spawn';
     7→import { writeLog } from '../shared/logging';
     8→import { ValidationError, CLINotFoundError } from '../shared/errors';
     9→import { detectClaudeCLI } from './cli-detector';
    10→import { buildClaudeArgs } from './cli-args';
    11→import { parseClaudeOutput } from './parser';
    12→import type { ClaudeOptions, ClaudeConfig } from './types';
    13→import type { ClaudeStreamEvent } from './events';
    14→
    15→export type { ClaudeOptions, ClaudeConfig, ClaudeStreamEvent };
    16→export * from './events';
    17→
    18→/**
    19→ * Lightweight Claude adapter for executing CLI commands
    20→ */
    21→export class ClaudeAdapter {
    22→  private readonly cliPath: string;
    23→  private readonly config: ClaudeConfig;
    24→
    25→  /**
    26→   * Create a new Claude adapter
    27→   * @param config - Claude adapter configuration
    28→   */
    29→  constructor(config: ClaudeConfig = {}) {
    30→    // Detect or use provided CLI path
    31→    const detectedPath = config.cliPath || detectClaudeCLI();
    32→    if (!detectedPath) {
    33→      throw new CLINotFoundError('claude', 'Claude CLI not found. Please install Claude Code or set CLAUDE_CLI_PATH environment variable.');
    34→    }
    35→
    36→    this.cliPath = detectedPath;
    37→    this.config = config;
    38→  }
    39→
    40→  /**
    41→   * Execute a prompt with Claude CLI
    42→   * @template T - Expected output type (inferred from responseSchema)
    43→   * @param prompt - The prompt to execute
    44→   * @param options - Execution options
    45→   * @returns Promise resolving to execution response
    46→   */
    47→  async execute<T = string>(
    48→    prompt: string,
    49→    options: ClaudeOptions = {}
    50→  ): Promise<ExecutionResponse<T>> {
    51→    // Inline prompt validation (4 lines)
    52→    if (!prompt || typeof prompt !== 'string' || prompt.trim().length === 0) {
    53→      throw new ValidationError('Prompt must be a non-empty string');
    54→    }
    55→
    56→    // Merge constructor config with execute options
    57→    const mergedOptions: ClaudeOptions = {
    58→      ...this.config,
    59→      ...options,
    60→    };
    61→
    62→    // Build CLI arguments
    63→    const args = buildClaudeArgs(prompt, mergedOptions);
    64→
    65→    // Set up environment
    66→    let env: Record<string, string> | undefined;
    67→    if (mergedOptions.apiKey || mergedOptions.oauthToken) {
    68→      const envVars: Record<string, string> = {};
    69→      if (typeof mergedOptions.apiKey === 'string') {
    70→        envVars['ANTHROPIC_API_KEY'] = mergedOptions.apiKey;
    71→      }
    72→      if (typeof mergedOptions.oauthToken === 'string') {
    73→        envVars['CLAUDE_CODE_OAUTH_TOKEN'] = mergedOptions.oauthToken;
    74→      }
    75→      env = envVars;
    76→    }
    77→
    78→    // Set up JSONL parsing and OutputData creation for streaming
    79→    let lineBuffer = '';
    80→    let onStdout: ((chunk: string) => void) | undefined;
    81→    let turnStarted = false;
    82→    let accumulatedText = '';
    83→
    84→    if (mergedOptions.onEvent || mergedOptions.onOutput) {
    85→      onStdout = (chunk: string) => {
    86→        // Parse JSONL events from this chunk
    87→        const chunkEvents: StreamEvent[] = [];
    88→        let chunkText = '';
    89→
    90→        lineBuffer += chunk;
    91→        const lines = lineBuffer.split('\n');
    92→        lineBuffer = lines.pop() || '';
    93→
    94→        for (const line of lines) {
    95→          const trimmed = line.trim();
    96→          if (!trimmed) continue;
    97→
    98→          try {
    99→            const event = JSON.parse(trimmed);
   100→            chunkEvents.push(event);
   101→
   102→            // Extract text from assistant messages
   103→            if (event.type === 'assistant' && event.message?.content) {
   104→              const content = event.message.content;
   105→              if (Array.isArray(content)) {
   106→                for (const block of content) {
   107→                  if (block.type === 'text' && block.text) {
   108→                    chunkText += block.text;
   109→                  }
   110→                }
   111→              }
   112→            }
   113→
   114→            // onEvent handling
   115→            if (mergedOptions.onEvent) {
   116→              // Emit synthetic turn.started event when we see the first assistant message
   117→              if (!turnStarted && event.type === 'assistant') {
   118→                turnStarted = true;
   119→                mergedOptions.onEvent({
   120→                  type: 'turn.started',
   121→                  timestamp: event.timestamp || Date.now(),
   122→                });
   123→              }
   124→
   125→              // Emit the original event
   126→              mergedOptions.onEvent(event);
   127→
   128→              // Emit synthetic events for backward compatibility
   129→              if (event.type === 'assistant' && event.message?.content) {
   130→                const content = event.message.content;
   131→                if (Array.isArray(content)) {
   132→                  for (const block of content) {
   133→                    // Emit text events
   134→                    if (block.type === 'text' && block.text) {
   135→                      mergedOptions.onEvent({
   136→                        type: 'text',
   137→                        data: { text: block.text },
   138→                        timestamp: event.timestamp || Date.now(),
   139→                      });
   140→                    }
   141→                    // Emit tool.started events for tool_use blocks
   142→                    if (block.type === 'tool_use' && block.name) {
   143→                      mergedOptions.onEvent({
   144→                        type: 'tool.started',
   145→                        data: {
   146→                          toolName: block.name,
   147→                          name: block.name,
   148→                          id: block.id,
   149→                          input: block.input,
   150→                        },
   151→                        timestamp: event.timestamp || Date.now(),
   152→                      });
   153→                    }
   154→                  }
   155→                }
   156→              }
   157→
   158→              // Emit tool.completed for user messages
   159→              if (event.type === 'user' && event.message?.content) {
   160→                const content = event.message.content;
   161→                if (Array.isArray(content)) {
   162→                  for (const block of content) {
   163→                    if (block.type === 'tool_result' && block.tool_use_id) {
   164→                      mergedOptions.onEvent({
   165→                        type: 'tool.completed',
   166→                        data: {
   167→                          toolId: block.tool_use_id,
   168→                          result: block.content,
   169→                          isError: block.is_error || false,
   170→                        },
   171→                        timestamp: event.timestamp || Date.now(),
   172→                      });
   173→                    }
   174→                  }
   175→                }
   176→              }
   177→
   178→              // Emit synthetic turn.completed event
   179→              if (event.type === 'result') {
   180→                mergedOptions.onEvent({
   181→                  type: 'turn.completed',
   182→                  timestamp: event.timestamp || Date.now(),
   183→                });
   184→              }
   185→            }
   186→          } catch {
   187→            // Not valid JSON, skip line
   188→          }
   189→        }
   190→
   191→        // Update accumulated text
   192→        if (chunkText) {
   193→          accumulatedText += chunkText;
   194→        }
   195→
   196→        // Call onOutput with enhanced OutputData
   197→        if (mergedOptions.onOutput) {
   198→          mergedOptions.onOutput({
   199→            raw: chunk,
   200→            events: chunkEvents.length > 0 ? chunkEvents : undefined,
   201→            text: chunkText || undefined,
   202→            accumulated: accumulatedText,
   203→          });
   204→        }
   205→      };
   206→    }
   207→
   208→    // Execute CLI
   209→    const result = await spawnProcess(this.cliPath, {
   210→      args,
   211→      cwd: mergedOptions.workingDir,
   212→      env,
   213→      timeout: mergedOptions.timeout,
   214→      onStdout,
   215→      onStderr: (chunk: string) => {
   216→        if (mergedOptions.verbose) {
   217→          process.stderr.write(chunk);
   218→        }
   219→      },
   220→      verbose: mergedOptions.verbose,
   221→    });
   222→
   223→    // Parse output
   224→    const response = await parseClaudeOutput<T>(
   225→      result.stdout,
   226→      result.duration,
   227→      result.exitCode,
   228→      mergedOptions.responseSchema
   229→    );
   230→
   231→    // Optional logging
   232→    if (mergedOptions.logPath) {
   233→      await writeLog(
   234→        mergedOptions.logPath,
   235→        { prompt, options: mergedOptions },
   236→        response,
   237→        response.status === 'error' ? response.error : undefined
   238→      );
   239→    }
