/**
 * Codex CLI Adapter
 */

import type { ExecutionResponse, StreamEvent } from '../shared/types';
import { spawnProcess } from '../shared/spawn';
import { writeLog } from '../shared/logging';
import { ValidationError, CLINotFoundError } from '../shared/errors';
import { detectCodexCLI } from './cli-detector';
import { buildCodexArgs } from './cli-args';
import { parseCodexOutput } from './parser';
import type { CodexOptions, CodexConfig } from './types';
import type { CodexStreamEvent } from './events';

export type { CodexOptions, CodexConfig, CodexStreamEvent };
export * from './events';

/**
 * Lightweight Codex adapter for executing CLI commands
 */
export class CodexAdapter {
  private readonly cliPath: string;
  private readonly config: CodexConfig;

  /**
   * Create a new Codex adapter
   * @param config - Codex adapter configuration
   */
  constructor(config: CodexConfig = {}) {
    // Detect or use provided CLI path
    const detectedPath = config.cliPath || detectCodexCLI();
    if (!detectedPath) {
      throw new CLINotFoundError('codex', 'Codex CLI not found. Please install Codex or set CODEX_CLI_PATH environment variable.');
    }

    this.cliPath = detectedPath;
    this.config = config;
  }

  /**
   * Execute a prompt with Codex CLI
   * @template T - Expected output type (inferred from responseSchema)
   * @param prompt - The prompt to execute
   * @param options - Execution options
   * @returns Promise resolving to execution response
   */
  async execute<T = string>(
    prompt: string,
    options: CodexOptions = {}
  ): Promise<ExecutionResponse<T>> {
    // Inline prompt validation (4 lines)
    if (!prompt || typeof prompt !== 'string' || prompt.trim().length === 0) {
      throw new ValidationError('Prompt must be a non-empty string');
    }

    // Merge constructor config with execute options
    const mergedOptions: CodexOptions = {
      ...this.config,
      ...options,
    };

    // Build CLI arguments
    const args = buildCodexArgs(prompt, mergedOptions, mergedOptions.sessionId);

    // Set up JSONL parsing and OutputData creation for streaming
    let lineBuffer = '';
    let onStdout: ((chunk: string) => void) | undefined;
    let turnStarted = false;
    let accumulatedText = '';

    if (mergedOptions.onEvent || mergedOptions.onOutput) {
      onStdout = (chunk: string) => {
        // Parse JSONL events from this chunk
        const chunkEvents: StreamEvent[] = [];
        let chunkText = '';

        lineBuffer += chunk;
        const lines = lineBuffer.split('\n');
        lineBuffer = lines.pop() || '';

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed) continue;

          try {
            const event = JSON.parse(trimmed);
            chunkEvents.push(event);

            // Extract text from item.completed events with agent_message type
            if (event.type === 'item.completed') {
              const data = event.data as Record<string, unknown>;
              const item = data?.item as Record<string, unknown>;
              if (
                item?.type === 'agent_message' &&
                item?.text &&
                typeof item.text === 'string'
              ) {
                chunkText += item.text;
              }
            }

            // onEvent handling
            if (mergedOptions.onEvent) {
              // Emit synthetic turn.started event when we see the first item
              if (!turnStarted && event.type === 'item.completed') {
                turnStarted = true;
                mergedOptions.onEvent({
                  type: 'turn.started',
                  timestamp: event.timestamp || Date.now(),
                });
              }

              // Emit the original event
              mergedOptions.onEvent(event);

              // Emit synthetic turn.completed event
              if (event.type === 'turn.completed') {
                mergedOptions.onEvent({
                  type: 'turn.completed',
                  timestamp: event.timestamp || Date.now(),
                  data: event.data,
                });
              }
            }
          } catch {
            // Not valid JSON, skip line
          }
        }

        // Update accumulated text
        if (chunkText) {
          accumulatedText += chunkText;
        }

        // Call onOutput with enhanced OutputData
        if (mergedOptions.onOutput) {
          mergedOptions.onOutput({
            raw: chunk,
            events: chunkEvents.length > 0 ? chunkEvents : undefined,
            text: chunkText || undefined,
            accumulated: accumulatedText,
          });
        }
      };
    }

    // Execute CLI
    const result = await spawnProcess(this.cliPath, {
      args,
      cwd: mergedOptions.workingDir,
      timeout: mergedOptions.timeout,
      onStdout,
      onStderr: (chunk: string) => {
        if (mergedOptions.verbose) {
          process.stderr.write(chunk);
        }
      },
    });

    // Parse output
    const response = await parseCodexOutput<T>(
      result.stdout,
      result.duration,
      result.exitCode,
      mergedOptions.responseSchema
    );

    // Optional logging
    if (mergedOptions.logPath) {
      await writeLog(
        mergedOptions.logPath,
        { prompt, options: mergedOptions },
        response,
        response.status === 'error' ? response.error : undefined
      );
    }

    return response;
  }
}

import type { ExecutionResponse, StreamEvent, TokenUsage } from "../shared/types";
import { extractJSON } from "../shared/json-parser";

/**
 * Parse Codex CLI output
 * Based on Codex CLI 0.46.0 event format
 * @param stdout Raw stdout from CLI
 * @param duration Execution duration in ms
 * @param exitCode CLI exit code
 * @param responseSchema Optional response schema for validation
 * @returns Parsed execution response
 */
export async function parseCodexOutput<T = string>(
  stdout: string,
  duration: number,
  exitCode: number,
  responseSchema?: true | { safeParse: (data: unknown) => { success: boolean; data?: unknown; error?: { message: string } } }
): Promise<ExecutionResponse<T>> {
  const events = parseStreamEvents(stdout);

  // Extract thread ID (session ID)
  const sessionId = extractThreadId(events);

  // Extract final text output from agent_message items
  let output: T;
  const agentMessages = events
    .filter((e) => {
      if (e.type !== "item.completed") return false;
      const data = e.data as Record<string, unknown>;
      return (data?.item as Record<string, unknown>)?.type === "agent_message";
    })
    .map((e) => {
      const data = e.data as Record<string, unknown>;
      return (data?.item as Record<string, unknown>)?.text;
    })
    .filter(Boolean);

  const lastMessage = agentMessages[agentMessages.length - 1];

  if (responseSchema) {
    // Extract and validate JSON
    const jsonResult = extractJSON((typeof lastMessage === 'string' ? lastMessage : '') || stdout);
    if (responseSchema === true) {
      output = jsonResult as T;
    } else if (responseSchema.safeParse) {
      const parseResult = responseSchema.safeParse(jsonResult);
      if (!parseResult.success) {
        throw new Error(
          `Response validation failed: ${parseResult.error?.message || 'Unknown validation error'}`
        );
      }
      output = parseResult.data as T;
    } else {
      output = jsonResult as T;
    }
  } else {
    // Plain text output - join all agent messages
    output = (agentMessages.join('\n') || stdout.trim()) as T;
  }

  // Build response
  const response: ExecutionResponse<T> = {
    data: output,
    events,
    sessionId: sessionId || generateSessionId(),
    status: exitCode === 0 ? "success" : "error",
    exitCode,
    duration,
    metadata: {
      toolsUsed: extractToolsUsed(events),
      filesModified: extractFilesModified(events),
    },
    raw: {
      stdout,
      stderr: "",
    },
  };

  // Add usage information if available
  const usage = extractUsage(events);
  if (usage) {
    response.usage = usage;
  }

  return response;
}

/**
 * Parse JSONL stream events
 * @param output Raw CLI output
 * @returns Array of parsed events
 */
function parseStreamEvents(output: string): StreamEvent[] {
  const lines = output.split("\n").filter((line) => line.trim());
  const events: StreamEvent[] = [];

  for (const line of lines) {
    try {
      const event = JSON.parse(line);
      events.push({
        type: event.type || "unknown",
        data: event.data || event,
        timestamp: event.timestamp || Date.now(),
      });
    } catch {
      // Not a JSON line, skip
    }
  }

  return events;
}

/**
 * Extract tools used from events
 * @param events Stream events
 * @returns Array of tool names
 */
function extractToolsUsed(events: StreamEvent[]): string[] {
  const tools = new Set<string>();

  for (const event of events) {
    if (event.type === "tool.started" || event.type === "tool_use") {
      const data = event.data as Record<string, unknown>;
      const toolName = data?.toolName || data?.name;
      if (typeof toolName === 'string') {
        tools.add(toolName);
      }
    }
  }

  return Array.from(tools);
}

/**
 * Extract files modified from events
 * @param events Stream events
 * @returns Array of file paths
 */
function extractFilesModified(events: StreamEvent[]): string[] {
  const files = new Set<string>();

  for (const event of events) {
    if (event.type === "file.written" || event.type === "file.modified") {
      const data = event.data as Record<string, unknown>;
      const filePath = data?.path || data?.file;
      if (typeof filePath === 'string') {
        files.add(filePath);
      }
    }
  }

  return Array.from(files);
}

/**
 * Extract token usage from events
 * Codex uses turn.completed events with usage field
 * @param events Stream events
 * @returns Token usage information
 */
function extractUsage(events: StreamEvent[]): TokenUsage | null {
  // Look for turn.completed events which contain usage
  const turnCompleted = events.find((e) => e.type === "turn.completed");
  if (turnCompleted?.data?.usage) {
    const usage = turnCompleted.data.usage as Record<string, unknown>;
    return {
      inputTokens: Number(usage.input_tokens) || 0,
      outputTokens: Number(usage.output_tokens) || 0,
      totalTokens: Number(usage.total_tokens) || (Number(usage.input_tokens) || 0) + (Number(usage.output_tokens) || 0),
    };
  }

  // Fallback for other event types
  for (const event of events) {
    if (event.type === "usage" || event.type === "completion") {
      if (event.data?.usage) {
        const usage = event.data.usage as Record<string, unknown>;
        return {
          inputTokens: Number(usage.input_tokens) || 0,
          outputTokens: Number(usage.output_tokens) || 0,
          totalTokens: Number(usage.total_tokens) || (Number(usage.input_tokens) || 0) + (Number(usage.output_tokens) || 0),
        };
      }
    }
  }

  return null;
}

/**
 * Extract thread ID (session ID) from events
 * @param events Stream events
 * @returns Thread ID or null
 */
function extractThreadId(events: StreamEvent[]): string | null {
  const threadStarted = events.find((e) => e.type === "thread.started");
  if (threadStarted) {
    const data = threadStarted.data as Record<string, unknown>;
    const threadId = data?.thread_id;
    if (typeof threadId === 'string') {
      return threadId;
    }
  }
  return null;
}

/**
 * Generate a session ID
 * @returns Session ID string
 */
function generateSessionId(): string {
  return `codex-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
}

/**
 * Codex-specific types
 * Based on Codex CLI 0.46.0
 */

import type { ExecutionOptions } from '../shared/types';

/**
 * Sandbox modes for Codex execution
 * Controls what file system operations the model can perform
 */
export type SandboxMode = 'read-only' | 'workspace-write' | 'danger-full-access';

/**
 * Codex-specific configuration
 */
export interface CodexConfig {
  /** Path to codex CLI executable */
  cliPath?: string;
  /** Working directory for the agent */
  workingDir?: string;
  /** Model to use (e.g., 'gpt-5', 'o3') */
  model?: string;
  /** Sandbox policy */
  sandbox?: SandboxMode;
  /** Enable web search tool */
  search?: boolean;
  /** Configuration profile from config.toml */
  profile?: string;
  /** Use open source model provider (requires Ollama) */
  oss?: boolean;
  /** Allow additional configuration options */
  [key: string]: unknown;
}

/**
 * Codex-specific execution options
 *
 * NOTE: Codex exec does not support approval policy flags.
 * Use fullAuto or dangerouslyBypassApprovalsAndSandbox instead.
 */
export interface CodexOptions extends ExecutionOptions {
  /** Model to use for this execution */
  model?: string;
  /** Sandbox policy for this execution */
  sandbox?: SandboxMode;
  /** Convenience flag for --full-auto (bypasses approvals with safe defaults) */
  fullAuto?: boolean;
  /** EXTREMELY DANGEROUS: Skip all confirmations and sandboxing */
  dangerouslyBypassApprovalsAndSandbox?: boolean;
  /** Image file paths to attach */
  images?: string[];
  /** Enable web search */
  search?: boolean;
  /** Skip git repo check */
  skipGitRepoCheck?: boolean;
  /** Path to JSON Schema file for output validation */
  outputSchema?: string;
  /** Color output setting */
  color?: 'always' | 'never' | 'auto';
  /** Enable JSONL output */
  json?: boolean;
  /** Include plan tool in conversation */
  includePlanTool?: boolean;
  /** File path to write last message */
  outputLastMessage?: string;
  /** Configuration overrides (key=value pairs) */
  config?: Record<string, unknown>;
  /** Configuration profile */
  profile?: string;
  /** Use OSS model provider */
  oss?: boolean;
}

